from __future__ import print_function

import logging
import os


class ErrorsHandlerToolsHolder:
    """
    Class for holding information about KPI's errors and
    providing errors finding tools
    """

    def __init__(self, source_file_path, release):
        self.adjustment = 0
        self.found_errors = list()
        self.arithmetic_operators = ['+', '/', '-', '*', "(", ")", '.', ',']
        self.formula_fragments_to_capitalize = ["sum", "power", "avg", "max", "min", "log"]
        self.accurate_phrases_used_in_formulas = ["PERIOD_DURATION", "MEASUREMENT_DURATION"]
        self.counters_from_formula = set()
        self.filtered_kpis = list()
        self.potential_unintended_phrases = list()
        self.suspicious_counters = list()
        self.KPIs_with_errors = dict()
        self.logger = self.__configure_logger(source_file_path, release)
        self.colors = {"<gr>": "\x1b[1;32m", "</gr>": "\x1b[0m",
                       "<yel>": "\x1b[1;33m", "</yel>": "\x1b[0m",
                       "<red>": "\033[91m", "</red>": "\033[00m"}

    @staticmethod
    def first_non_blank_space(examined_string):
        """
        Check for first non whitespace character

        :param examined_string: String which is beeing examined

        :return: Index of first non whitespace character
        """
        for i, char in enumerate(examined_string):
            if char != " ":
                return i
        return 0

    def is_arithmetic(self, character):
        """
        Checks if passed character is one of defined in self.__arithmetic_operators list

        :param character: usually current char in loop iterating over KPI formula .
        :return: True or False
        """
        return character in self.arithmetic_operators

    @staticmethod
    def __configure_logger(source_file_path, release):
        """
        Configures logger used through up time of the script

        :param source_file_path: Path to xml release file
        :param release: Release ID parsed from xml file

        :return: Configured logger
        """
        savable_source_file_path = os.path.dirname(source_file_path) + '/'
        log_format = "%(levelname)s %(asctime)s - %(message)s"
        logging.basicConfig(filename="{}release_{}.log".format(savable_source_file_path, release),
                            level=logging.DEBUG, filemode='w', format=log_format)
        return logging.getLogger()

    class ErrorsPrinter:
        def __init__(self):
            pass

        @staticmethod
        def print_recursively(to_print, formula):
            """
            Recursive printing, in each recursion formula is truncated to the last index
            of to_print fragment and first element of to_print list is removed

            :param to_print: contains fragments of the formula, usually bug fragments which are colored
            :param formula: formula to print

            :return: If there is no more to_print elements
            """
            try:
                if len(to_print):
                    phrase_index = formula.find(to_print[0])
                    print("{}\x1b[1;33m{}\x1b[0m".format(formula[:phrase_index], to_print[0]), end='')
                    length_of_previous_element = len(to_print[0])
                    to_print.remove(to_print[0])
                    ErrorsHandlerToolsHolder.ErrorsPrinter.print_recursively(to_print, formula[phrase_index + length_of_previous_element:])
                else:
                    print(formula)
                    return
            except Exception as other_errors:
                print(other_errors, "occurred when printing recursively")

        @staticmethod
        def info_print(to_print_message, to_print_content="", end='\n'):
            print("\x1b[1;32m Info : {} \x1b[0m {}".format(to_print_message, to_print_content), end=end)

        @staticmethod
        def warn_print(to_print_message, to_print_content="", end='\n'):
            print("\x1b[1;33m Warning : {} \x1b[0m {}".format(to_print_message, to_print_content), end=end)

        @staticmethod
        def error_print(to_print_message, to_print_content="", end='\n'):
            print("\033[91m Error : {} \033[00m {}".format(to_print_message, to_print_content), end=end)
